using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Shapes;
using Microsoft.Win32;
using FacialPresets;
namespace DanceStudio;
public sealed class FacialTrackEditor:UserControl {
 MfeeCatalog catalog=MfeeCatalog.Documented();readonly Window? dialogOwner;readonly TimelineAxis axis;bool scrubbing;readonly SongProject project;readonly Action changed;readonly Action<double> seek;readonly Func<double> cursor;
 readonly StackPanel tracks=new(),fields=new();readonly TextBox start=new(),end=new(),gain=new(),fadeIn=new(),fadeOut=new(),speed=new(),offset=new();readonly ComboBox channel=new(){ItemsSource=new[]{"all","emotion","eyes","mouth"},SelectedIndex=0};FacialSegment? selected;double renderWidth=930;readonly Dictionary<string,bool> expanded=new();
 readonly Dictionary<Guid,Border> blocks=new();readonly List<(Line line,double scale)> playheads=[];
 readonly TextBlock selectionLabel=new(){TextWrapping=TextWrapping.Wrap};readonly List<Button> selectionButtons=[];FrameworkElement? editorRoot;double shownCursor=double.NaN;
 sealed record ChannelChoice(string Id,string Label);
 public FacialTrackEditor(SongProject p,Func<double> position,Action<double> onSeek,Action onChanged,Window? owner=null,TimelineAxis? viewport=null){
  dialogOwner=owner;axis=viewport??new TimelineAxis();project=p;cursor=position;seek=onSeek;changed=onChanged;StudioTheme.Install();
  Loaded+=OnLoaded;Unloaded+=OnUnloaded;
  var root=new DockPanel{Margin=new Thickness(0),MinWidth=660};editorRoot=root;Content=new ScrollViewer{Content=root,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};
  root.SizeChanged+=(_,_)=>{if(Math.Abs(renderWidth-root.ActualWidth)>.5){renderWidth=root.ActualWidth;Draw();}};
  var top=new WrapPanel();DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);
  channel.ItemsSource=new[]{new ChannelChoice("all",UiText.T("uiAllChannels")),new ChannelChoice("emotion",UiText.T("facial018")),new ChannelChoice("eyes",UiText.T("facial019")),new ChannelChoice("mouth",UiText.T("facial020"))};channel.DisplayMemberPath="Label";channel.SelectedValuePath="Id";channel.SelectedIndex=0;channel.MinWidth=140;channel.Margin=new Thickness(0,0,10,6);channel.ToolTip=UiText.T("uiChannelTip");top.Children.Add(channel);
  AddButton(top,UiText.T("facial004"),Import);AddButton(top,UiText.T("facial005"),ImportClip);
  AddButton(top,UiText.T("mfeeCatalog"),()=>{var file=new OpenFileDialog{Filter="MFEE catalog|*.json"};if(file.ShowDialog(dialogOwner??Window.GetWindow(this))==true){catalog=MfeeCatalog.Load(file.FileName);}});
  foreach(var (label,id) in new[]{(UiText.T("facialVowel0"),"a"),(UiText.T("facialVowel1"),"i"),(UiText.T("facialVowel2"),"u"),(UiText.T("facialVowel3"),"e"),(UiText.T("facialVowel4"),"o")})AddButton(top,label,()=>{var entry=catalog.Vowel(id)??throw new InvalidOperationException(UiText.T("mfeeNoVowel"));var preset=new Preset{Name=label};preset.Channels["mouth"].Morphs.Add(new(){Backend="MFEE",Id=entry.Id,Name=entry.Name,Strength=25});Place(preset,"mouth");});
  var legend=new TextBlock{Text=UiText.T("uiTypeLegend"),ToolTip=UiText.T("mfeePolicy"),Foreground=StudioTheme.Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,10),FontSize=11};DockPanel.SetDock(legend,Dock.Top);root.Children.Add(legend);
  var bottom=new StackPanel{Margin=new Thickness(0,12,0,0)};var properties=new Expander{Header=UiText.T("timelineProperties"),IsExpanded=false,Content=bottom};DockPanel.SetDock(properties,Dock.Bottom);root.Children.Add(properties);selectionLabel.Foreground=StudioTheme.Accent;selectionLabel.Margin=new Thickness(0,0,0,8);bottom.Children.Add(selectionLabel);
  var fieldWrap=new WrapPanel();var clipWrap=new WrapPanel();var fieldRows=new StackPanel();fieldRows.Children.Add(fieldWrap);fieldRows.Children.Add(clipWrap);bottom.Children.Add(StudioTheme.Card(fieldRows));fields.IsEnabled=false;
  foreach(var (label,box,unit) in new[]{(UiText.T("facial006"),start,"s"),(UiText.T("facial007"),end,"s"),(UiText.T("facial008"),gain,"×"),(UiText.T("facial009"),fadeIn,"s"),(UiText.T("facial010"),fadeOut,"s"),(UiText.T("facial011"),speed,"×"),(UiText.T("facial012"),offset,"s")}){
   var panel=new StackPanel{Width=142,Margin=new Thickness(0,0,12,10)};panel.Children.Add(new TextBlock{Text=label+"  ·  "+unit,Foreground=StudioTheme.Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,5)});box.ToolTip=label+" ("+unit+")";box.MinWidth=100;panel.Children.Add(box);(box==speed||box==offset?clipWrap:fieldWrap).Children.Add(panel);
  }
  var actions=new WrapPanel{Margin=new Thickness(0,8,0,0)};bottom.Children.Add(actions);var apply=AddButton(actions,UiText.T("facial013"),Apply);apply.Style=(Style)Application.Current.FindResource("Studio.Primary");selectionButtons.Add(apply);var remove=AddButton(actions,UiText.T("facial014"),Remove);remove.Style=(Style)Application.Current.FindResource("Studio.Delete");selectionButtons.Add(remove);
  root.Children.Add(tracks);Select(null);Draw();
 }
 void OnLoaded(object sender,RoutedEventArgs e){CompositionTarget.Rendering-=RenderCursor;CompositionTarget.Rendering+=RenderCursor;axis.Changed-=Redraw;axis.Changed+=Redraw;Draw();}
 void OnUnloaded(object sender,RoutedEventArgs e){CompositionTarget.Rendering-=RenderCursor;axis.Changed-=Redraw;if(Mouse.Captured is DependencyObject element&&IsAncestorOf(element))Mouse.Capture(null);scrubbing=false;}
 void Redraw()=>Draw();
 public void RefreshTimeline()=>Draw();
 static Button AddButton(Panel p,string label,Action action){var b=new Button{Content=label,ToolTip=label};b.Click+=(_,_)=>{try{action();}catch(Exception e){MessageBox.Show(UiText.Error(e.Message),UiText.T("facial015"));}};p.Children.Add(b);return b;}
 void RenderCursor(object? sender,EventArgs args){if(editorRoot?.IsVisible!=true)return;double t=cursor();if(t==shownCursor)return;shownCursor=t;foreach(var (line,scale) in playheads){line.X1=line.X2=(t-axis.Start)*scale+TimelineAxis.Left;line.Visibility=t>=axis.Start&&t<=axis.Start+axis.Span?Visibility.Visible:Visibility.Hidden;}}
 void Import(){var dialog=new OpenFileDialog{Filter=UiText.T("facial016")};if(dialog.ShowDialog(dialogOwner??Window.GetWindow(this))==true)Place(PresetFile.Load(dialog.FileName),channel.SelectedValue as string??"all");}
 void Place(Preset preset,string target){var additions=preset.Channels.Where(kv=>(target=="all"||kv.Key==target)&&kv.Value.Morphs.Count>0).Select(kv=>new FacialSegment{Channel=kv.Key,Start=cursor(),End=cursor()+1,Preset=FacialTimeline.Copy(preset)}).ToList();var combined=project.FacialTracks.Concat(additions).ToList();FacialTimeline.Validate(combined);project.FacialTracks=combined;changed();Draw();}
 void ImportClip(){var d=new OpenFileDialog{Filter=UiText.T("facial017")};if(d.ShowDialog(dialogOwner??Window.GetWindow(this))!=true)return;var clip=FacialClipFile.Load(d.FileName);var channels=clip.Keys.SelectMany(k=>k.State.Channels.Where(c=>c.Value.Morphs.Count>0).Select(c=>c.Key)).Distinct().Where(c=>channel.SelectedValue as string=="all"||channel.SelectedValue as string==c).ToList();MessageBox.Show($"{clip.Name} / {clip.Duration:0.###} s / {string.Join(", ",channels)}");var all=project.FacialTracks.Concat(channels.Select(c=>new FacialSegment{Channel=c,Start=cursor(),End=cursor()+clip.Duration,Clip=System.Text.Json.JsonSerializer.Deserialize<FacialClip>(System.Text.Json.JsonSerializer.Serialize(clip))})).ToList();FacialTimeline.Validate(all);project.FacialTracks=all;changed();Draw();}
 void Select(FacialSegment? c){selected=c;foreach(var box in new[]{start,end,gain,fadeIn,fadeOut,speed,offset})box.IsEnabled=c!=null;foreach(var button in selectionButtons)button.IsEnabled=c!=null;
  selectionLabel.Text=c==null?UiText.T("uiNoSelection"):(c.Clip==null?UiText.T("uiPreset"):UiText.T("uiClip"))+"  /  "+(c.Clip?.Name??c.Preset.Name);
  foreach(var (id,block) in blocks){block.BorderBrush=id==c?.Id?StudioTheme.Accent:(Brush)block.Tag;block.BorderThickness=new Thickness(id==c?.Id?2:1);}
  if(c==null){foreach(var box in new[]{start,end,gain,fadeIn,fadeOut,speed,offset})box.Text="";return;}
  speed.IsEnabled=offset.IsEnabled=c.Clip!=null;speed.Text=c.PlaybackSpeed.ToString("R",System.Globalization.CultureInfo.InvariantCulture);offset.Text=c.SourceOffset.ToString("R",System.Globalization.CultureInfo.InvariantCulture);start.Text=c.Start.ToString("R",System.Globalization.CultureInfo.InvariantCulture);end.Text=c.End.ToString("R",System.Globalization.CultureInfo.InvariantCulture);gain.Text=c.Gain.ToString("R",System.Globalization.CultureInfo.InvariantCulture);fadeIn.Text=c.FadeIn.ToString("R",System.Globalization.CultureInfo.InvariantCulture);fadeOut.Text=c.FadeOut.ToString("R",System.Globalization.CultureInfo.InvariantCulture);
 }
 static Brush ChannelBrush(string channel)=>channel=="emotion"?StudioTheme.Brush("#AB8EE5"):channel=="eyes"?StudioTheme.Brush("#70A9EC"):StudioTheme.Brush("#52C3A5");
 void Apply(){if(selected==null)return;double Read(TextBox b)=>double.Parse(b.Text,System.Globalization.CultureInfo.InvariantCulture);var c=selected;var old=(c.Start,c.End,c.Gain,c.FadeIn,c.FadeOut,c.PlaybackSpeed,c.SourceOffset);try{c.PlaybackSpeed=Read(speed);c.SourceOffset=Read(offset);if(c.Clip!=null&&c.PlaybackSpeed!=old.PlaybackSpeed)c.End=c.Start+(c.End-c.Start)*old.PlaybackSpeed/c.PlaybackSpeed;double newStart=Read(start);if(c.Clip!=null&&c.PlaybackSpeed!=old.PlaybackSpeed&&Read(end)==old.End)c.End+=newStart-old.Start;c.Start=newStart;if(c.Clip==null||Read(end)!=old.End)c.End=Read(end);c.Gain=Read(gain);c.FadeIn=Read(fadeIn);c.FadeOut=Read(fadeOut);FacialTimeline.Validate(project.FacialTracks);}catch{(c.Start,c.End,c.Gain,c.FadeIn,c.FadeOut,c.PlaybackSpeed,c.SourceOffset)=old;throw;}changed();Select(c);Draw();}
 void Remove(){if(selected==null)return;project.FacialTracks.Remove(selected);selected=null;changed();Draw();Select(null);}
 void Draw(){tracks.Children.Clear();blocks.Clear();playheads.Clear();double width=Math.Max(1,renderWidth),span=axis.Span;double scale=axis.Width(width)/span;
  if(MfeePolicy.Legacy(project.FacialTracks).Any())tracks.Children.Add(new TextBlock{Text=UiText.T("mfeeLegacy"),Foreground=StudioTheme.Danger,TextWrapping=TextWrapping.Wrap});if(project.FacialTracks.Count==0)tracks.Children.Add(new TextBlock{Text=UiText.T("uiEmptyFacial"),Foreground=StudioTheme.Muted,Margin=new Thickness(12),TextWrapping=TextWrapping.Wrap});
  foreach(var (id,label) in new[]{("emotion",UiText.T("facial018")),("eyes",UiText.T("facial019")),("mouth",UiText.T("facial020"))}){var canvas=new Canvas{Height=60,Width=width,HorizontalAlignment=HorizontalAlignment.Left,Background=StudioTheme.Background,ClipToBounds=true};var expand=new Expander{Header=label,Style=(Style)Application.Current.FindResource("Studio.TrackExpander"),IsExpanded=!expanded.TryGetValue(id,out var state)||state,Content=canvas};expand.Expanded+=(_,_)=>expanded[id]=true;expand.Collapsed+=(_,_)=>expanded[id]=false;tracks.Children.Add(expand);
   var trackName=new TextBlock{Text=label,Foreground=StudioTheme.Muted,IsHitTestVisible=false};Canvas.SetLeft(trackName,8);Canvas.SetTop(trackName,34);canvas.Children.Add(trackName);
   foreach(var (t,x,major) in axis.Ticks(width)){canvas.Children.Add(new Line{X1=x,X2=x,Y1=major?23:27,Y2=60,Stroke=StudioTheme.Line,IsHitTestVisible=false});if(major&&x+100<width){var tick=new TextBlock{Text=TimelineView.Format(t),Foreground=StudioTheme.Muted,FontSize=11,IsHitTestVisible=false};Canvas.SetLeft(tick,x+4);canvas.Children.Add(tick);}}
   double ClampTime(double x)=>Math.Clamp(axis.Time(Math.Clamp(x,TimelineAxis.Left,width-TimelineAxis.Right),width),0,ProjectRules.MaxProjectTime);
   canvas.MouseLeftButtonDown+=(_,e)=>{var at=e.GetPosition(canvas);if(at.X<TimelineAxis.Left)return;if(e.Source==canvas||at.Y<25){scrubbing=true;canvas.CaptureMouse();seek(ClampTime(at.X));RenderCursor(null,EventArgs.Empty);e.Handled=true;}};
   canvas.MouseMove+=(_,e)=>{if(scrubbing&&canvas.IsMouseCaptured){seek(ClampTime(e.GetPosition(canvas).X));RenderCursor(null,EventArgs.Empty);e.Handled=true;}};
   canvas.MouseLeftButtonUp+=(_,e)=>{if(scrubbing){scrubbing=false;canvas.ReleaseMouseCapture();e.Handled=true;}};
   canvas.LostMouseCapture+=(_,_)=>scrubbing=false;
   canvas.MouseWheel+=(_,e)=>{e.Handled=true;if(Mouse.Captured!=null)return;axis.Zoom(e.GetPosition(canvas).X,width,e.Delta);e.Handled=true;};
   foreach(var c in project.FacialTracks.Where(c=>c.Channel==id)){if(c.End<axis.Start||c.Start>axis.Start+axis.Span)continue;var color=ChannelBrush(id);var labelGrid=new Grid{Margin=new Thickness(10,4,10,4),ClipToBounds=true};labelGrid.ColumnDefinitions.Add(new(){Width=GridLength.Auto});labelGrid.ColumnDefinitions.Add(new());var badge=new TextBlock{Text=c.Clip==null?"P":"C",Foreground=color,FontWeight=FontWeights.Bold,Margin=new Thickness(0,0,8,0),VerticalAlignment=VerticalAlignment.Center};labelGrid.Children.Add(badge);var title=new TextBlock{Text=c.Clip?.Name??c.Preset.Name,Foreground=StudioTheme.Text,TextTrimming=TextTrimming.CharacterEllipsis,VerticalAlignment=VerticalAlignment.Center};Grid.SetColumn(title,1);labelGrid.Children.Add(title);
    var block=new Border{Width=Math.Max(8,(c.End-c.Start)*scale),Height=28,Tag=color,CornerRadius=new CornerRadius(4),Background=StudioTheme.Input,BorderBrush=selected==c?StudioTheme.Accent:color,BorderThickness=new Thickness(selected==c?2:1),ToolTip=(c.Clip==null?UiText.T("uiPreset"):UiText.T("uiClip"))+" / "+(c.Clip?.Name??c.Preset.Name)+$"\n{c.Start:0.###} → {c.End:0.###} s\n"+UiText.T("uiDragTip")};blocks[c.Id]=block;
    var leftHandle=new Border{Width=4,Background=color,HorizontalAlignment=HorizontalAlignment.Left,IsHitTestVisible=false};var rightHandle=new Border{Width=4,Background=color,HorizontalAlignment=HorizontalAlignment.Right,IsHitTestVisible=false};var visual=new Grid();visual.Children.Add(labelGrid);visual.Children.Add(leftHandle);visual.Children.Add(rightHandle);block.Child=visual;Canvas.SetLeft(block,axis.X(c.Start,width));Canvas.SetTop(block,29);canvas.Children.Add(block);void ClipBlock(){double x=Canvas.GetLeft(block),left=Math.Clamp(TimelineAxis.Left-x,0,block.Width),right=Math.Clamp(width-TimelineAxis.Right-x,left,block.Width);block.Clip=new RectangleGeometry(new Rect(left,0,right-left,28));}ClipBlock();
    var menu=new ContextMenu();var remove=new MenuItem{Header=UiText.T("facial022"),Foreground=StudioTheme.Danger};remove.Click+=(_,_)=>{selected=c;Remove();};menu.Items.Add(remove);block.ContextMenu=menu;
    double x=0,oldStart=0,oldEnd=0,oldOffset=0,oldEnvelopeOffset=0;double? oldEnvelopeDuration=null;int edge=0;bool dragging=false;
    block.MouseLeftButtonDown+=(_,e)=>{Select(c);x=e.GetPosition(canvas).X;oldStart=c.Start;oldEnd=c.End;oldOffset=c.SourceOffset;oldEnvelopeOffset=c.EnvelopeOffset;oldEnvelopeDuration=c.EnvelopeDuration;var local=e.GetPosition(block).X;edge=local<8?-1:local>block.Width-8?1:0;dragging=true;block.CaptureMouse();e.Handled=true;};
    block.MouseMove+=(_,e)=>{if(!dragging){var local=e.GetPosition(block).X;block.Cursor=local<8||local>block.Width-8?Cursors.SizeWE:Cursors.SizeAll;return;}double delta=(e.GetPosition(canvas).X-x)/scale;if(edge==0){c.Start=Math.Clamp(oldStart+delta,0,Math.Max(0,ProjectRules.MaxProjectTime-(oldEnd-oldStart)));c.End=c.Start+oldEnd-oldStart;}else if(edge<0)c.Start=Math.Clamp(oldStart+delta,0,oldEnd-.001);else c.End=Math.Clamp(oldEnd+delta,oldStart+.001,ProjectRules.MaxProjectTime);if(edge!=0){c.EnvelopeDuration=oldEnvelopeDuration??(oldEnd-oldStart);c.EnvelopeOffset=oldEnvelopeOffset+(edge<0?c.Start-oldStart:0);if(edge<0&&c.Clip!=null)c.SourceOffset=oldOffset+(c.Start-oldStart)*c.PlaybackSpeed;}Canvas.SetLeft(block,axis.X(c.Start,width));block.Width=Math.Max(8,(c.End-c.Start)*scale);ClipBlock();Select(c);};
    block.MouseLeftButtonUp+=(_,e)=>{if(!dragging)return;dragging=false;block.ReleaseMouseCapture();try{FacialTimeline.Validate(project.FacialTracks);changed();}catch(Exception ex){c.Start=oldStart;c.End=oldEnd;c.SourceOffset=oldOffset;c.EnvelopeOffset=oldEnvelopeOffset;c.EnvelopeDuration=oldEnvelopeDuration;MessageBox.Show(UiText.Error(ex.Message));}Draw();Select(c);e.Handled=true;};
    block.LostMouseCapture+=(_,_)=>{if(dragging){dragging=false;c.Start=oldStart;c.End=oldEnd;c.SourceOffset=oldOffset;c.EnvelopeOffset=oldEnvelopeOffset;c.EnvelopeDuration=oldEnvelopeDuration;Select(c);Draw();}};
   }
   var head=new Line{X1=axis.X(cursor(),width),X2=axis.X(cursor(),width),Y1=20,Y2=60,Stroke=StudioTheme.Accent,StrokeThickness=2,IsHitTestVisible=false};canvas.Children.Add(head);playheads.Add((head,scale));
  }
  shownCursor=double.NaN;RenderCursor(null,EventArgs.Empty);
 }
}
